            if (Pdfsrc.PsMissed(src)) {
                return 1;
            }
        }
        return 0;
    }
    public static int PlSkip(emon.Port.Src src, int from, int end) {
        // The first index >= from that is neither white space nor inside a
        // comment (`%` to the end of the line), or end.
        int p = from;
        int c = 0;
        while (p < end) {
            c = Pdfsrc.PsU8(src, p);
            if (PlStalled(src, p) == 1) {
                return end;
            }
            if (PlIsWs(c) == 1) {
                p += 1;
            } else if (c == 37) {
                while ((p < end) && (Pdfsrc.PsU8(src, p) != 10) && (Pdfsrc.PsU8(src, p) != 13)) {
                    if (PlStalled(src, p) == 1) {
                        return end;
                    }
                    p += 1;
                }
            } else {
                return p;
            }
        }
        return p;
    }
    public static int PlKwAt(emon.Port.Src src, int p, int end, int id) {
        // 1 when the bytes of keyword `id` (an `emon.pdfnames` `pk` code)
        // are at p. No delimiter check: `endstream` is found inside data.
        int start = Pdfnames.PkSpan[(id - 1) * 2 + 0];
        int ln = Pdfnames.PkSpan[(id - 1) * 2 + 1];
        int k = 0;
        if ((p + ln) > end) {
            return 0;
        }
        while (k < ln) {
            if (Pdfsrc.PsU8(src, p + k) != Pdfnames.PkChars[start + k]) {
                return 0;
            }
            k += 1;
        }
        return 1;
    }
    internal static int PlKwIdOf(emon.Port.Src src, int s, int n) {
        // The `pk` id of the keyword in src[s, s+n), 0 for any other.
        int row = 0;
        int k = 0;
        int same = 0;
        while (row < 13) {
            if (Pdfnames.PkSpan[row * 2 + 1] == n) {
                same = 1;
                k = 0;
                while ((same == 1) && (k < n)) {
                    if (Pdfsrc.PsU8(src, s + k) != Pdfnames.PkChars[Pdfnames.PkSpan[row * 2 + 0] + k]) {
                        same = 0;
                    }
                    k += 1;
                }
                if (same == 1) {
                    return row + 1;
                }
            }
            row += 1;
        }
        return 0;
    }
    public static int PlTokenStart(emon.Port.Cells ar) {
        return emon.Port.CellsAt(ar, ATs);
    }
    public static int PlTokenA(emon.Port.Cells ar) {
        return emon.Port.CellsAt(ar, ATa);
    }
    public static int PlTokenC(emon.Port.Cells ar) {
        return emon.Port.CellsAt(ar, ATc);
    }
    internal static int PlTok(emon.Port.Cells ar, int kind, int s, int e, int a, int b, int c) {
        // Record a token, advance to its end, answer its kind.
        emon.Port.CellsSet(ar, ATk, kind);
        emon.Port.CellsSet(ar, ATs, s);
        emon.Port.CellsSet(ar, ATa, a);
        emon.Port.CellsSet(ar, ATb, b);
        emon.Port.CellsSet(ar, ATc, c);
        emon.Port.CellsSet(ar, APos, e);
        return kind;
    }
    internal static int PlTokErr(emon.Port.Cells ar, int s, int e, int code) {
        PlFail(ar, code);
        return PlTok(ar, 12, s, e, 0, 0, 0);
    }
    internal static int PlLexNumber(emon.Port.Src src, emon.Port.Cells ar, int s, int end) {
        // A number starting at s, or 0 (nothing consumed) when it is not one.
        // Tolerated: several signs (`--5` is -5), `.5`, `5.`, and trailing
        // junk (`12abc` is 12 and then `abc`). Integers saturate at 2^31-1;
        // a real keeps at most nine significant digits and twelve fractional.
        int q = s;
        int neg = 0;
        int iv = 0;
        int m = 0;
        int scale = 0;
        int nd = 0;
        int dot = 0;
        long wv = (long) 0;
        int d = 0;
        while ((q < end) && ((Pdfsrc.PsU8(src, q) == 43) || (Pdfsrc.PsU8(src, q) == 45))) {
            if (Pdfsrc.PsU8(src, q) == 45) {
                neg = 1;
            }
            q += 1;
        }
        while ((q < end) && (Pdfsrc.PsU8(src, q) >= 48) && (Pdfsrc.PsU8(src, q) <= 57)) {
            d = Pdfsrc.PsU8(src, q) - 48;
            if (iv <= 214748363) {
                iv = (iv * 10) + d;
            } else {
                iv = 2147483647;
            }
            if (m <= 99999999) {
                m = (m * 10) + d;
            } else {
                scale = -1000;
            }
            wv = unchecked(unchecked(wv * ((long) 10)) + ((long) d));
            nd += 1;
            q += 1;
        }
        if ((q < end) && (Pdfsrc.PsU8(src, q) == 46)) {
            dot = 1;
            q += 1;
            while ((q < end) && (Pdfsrc.PsU8(src, q) >= 48) && (Pdfsrc.PsU8(src, q) <= 57)) {
                d = Pdfsrc.PsU8(src, q) - 48;
                if ((m <= 99999999) && (scale >= 0) && (scale < 12)) {
                    m = (m * 10) + d;
                    scale += 1;
                }
                nd += 1;
                q += 1;
            }
        }
        if (nd == 0) {
            return 0;
        }
        if (dot == 0) {
            if (neg == 1) {
                iv = 0 - iv;
            }
            // The token's third value keeps the integer modulo 2^32, as a signed
            // pattern: /P in an encryption dictionary is often written unsigned
            // (4294965956 for -1340) and `iv` has saturated by then (P3.2).
            return PlTok(ar, 1, s, q, iv, 0, (int) wv);
        }
        // An integer part too long for nine digits saturates.
        if (scale < 0) {
            m = 999999999;
            scale = 0;
        }
        if (neg == 1) {
            m = 0 - m;
        }
        return PlTok(ar, 2, s, q, m, scale, 0);
    }
    internal static int PlLexName(emon.Port.Src src, emon.Port.Cells ar, int s, int end) {
        // A name; s is the index of the byte AFTER the slash. `#xx` becomes
        // a byte when two hex digits follow, else the `#` is kept.
        int q = s;
        int c = 0;
        int hi = 0;
        int lo = 0;
        PlInternBegin(ar);
        while ((q < end) && (PlRegular(Pdfsrc.PsU8(src, q)) == 1)) {
            c = Pdfsrc.PsU8(src, q);
            q += 1;
            if ((c == 35) && ((q + 1) < end)) {
                hi = PlHexval(Pdfsrc.PsU8(src, q));
                lo = PlHexval(Pdfsrc.PsU8(src, q + 1));
                if ((hi >= 0) && (lo >= 0)) {
                    c = (hi * 16) + lo;
                    q += 2;
                }
            }
            PlIb(ar, c);
        }
        int e = PlInternEnd(ar);
        return PlTok(ar, 3, s - 1, q, e, emon.Port.CellsAt(ar, e + 1), 0);
    }
    internal static int PlLexLit(emon.Port.Src src, emon.Port.Cells ar, int s, int end) {
        // A literal string; s is the index of the byte AFTER the `(`.
        // Escapes \n \r \t \b \f \( \) \\ and \ddd (one to three octal
        // digits, high bits dropped); a backslash before an end of line is a
        // continuation; an unknown escape keeps the character. An end of line
        // inside the string reads as one LF. Parentheses nest.
        int start = emon.Port.CellsLen(ar);
        int q = s;
        int depth = 1;
        int c = 0;
        int v = 0;
        int n = 0;
        while (q < end) {
            c = Pdfsrc.PsU8(src, q);
            q += 1;
            if (PlStalled(src, q) == 1) {
                emon.Port.CellsDrop(ar, start);
                return 12;
            }
            if (c == 92) {
                if (q >= end) {
                    PlTokErr(ar, s - 1, end, 3);
                    return 12;
                }
                c = Pdfsrc.PsU8(src, q);
                q += 1;
                if (c == 110) {
                    emon.Port.CellsPush(ar, 10);
                } else if (c == 114) {
                    emon.Port.CellsPush(ar, 13);
                } else if (c == 116) {
                    emon.Port.CellsPush(ar, 9);
                } else if (c == 98) {
                    emon.Port.CellsPush(ar, 8);
                } else if (c == 102) {
                    emon.Port.CellsPush(ar, 12);
                } else if ((c >= 48) && (c <= 55)) {
                    v = c - 48;
                    n = 1;
                    while ((n < 3) && (q < end) && (Pdfsrc.PsU8(src, q) >= 48) && (Pdfsrc.PsU8(src, q) <= 55)) {
                        v = (v * 8) + (Pdfsrc.PsU8(src, q) - 48);
                        q += 1;
                        n += 1;
                    }
                    emon.Port.CellsPush(ar, v & 255);
                } else if (c == 13) {
                    if ((q < end) && (Pdfsrc.PsU8(src, q) == 10)) {
                        q += 1;
                    }
                } else if (c == 10) {
                    q += 0;
                } else {
                    emon.Port.CellsPush(ar, c);
                }
            } else if (c == 40) {
                depth += 1;
                emon.Port.CellsPush(ar, 40);
            } else if (c == 41) {
                depth -= 1;
                if (depth == 0) {
                    return PlTok(ar, 4, s - 1, q, start, emon.Port.CellsLen(ar) - start, 0);
                }
                emon.Port.CellsPush(ar, 41);
            } else if (c == 13) {
                if ((q < end) && (Pdfsrc.PsU8(src, q) == 10)) {
                    q += 1;
                }
                emon.Port.CellsPush(ar, 10);
            } else {
                emon.Port.CellsPush(ar, c);
            }
        }
        emon.Port.CellsDrop(ar, start);
        PlTokErr(ar, s - 1, end, 3);
        return 12;
    }
    internal static int PlLexHex(emon.Port.Src src, emon.Port.Cells ar, int s, int end) {
        // A hex string; s is the index of the byte AFTER the `<`. White space
        // and any non-hex byte are ignored; an odd last digit is followed by 0.
        int start = emon.Port.CellsLen(ar);
        int q = s;
        int c = 0;
        int v = 0;
        int half = -1;
        while (q < end) {
            c = Pdfsrc.PsU8(src, q);
            q += 1;
            if (PlStalled(src, q) == 1) {
                emon.Port.CellsDrop(ar, start);
                return 12;
            }
            if (c == 62) {
                if (half >= 0) {
                    emon.Port.CellsPush(ar, half * 16);
                }
                return PlTok(ar, 4, s - 1, q, start, emon.Port.CellsLen(ar) - start, 1);
            }
            v = PlHexval(c);
            if (v >= 0) {
                if (half < 0) {
                    half = v;
                } else {
                    emon.Port.CellsPush(ar, (half * 16) + v);
                    half = -1;
                }
            }
        }
        emon.Port.CellsDrop(ar, start);
        PlTokErr(ar, s - 1, end, 3);
        return 12;
    }
    public static int PlLex(emon.Port.Src src, emon.Port.Cells ar) {
        // The next token: answers its kind (T_*) and leaves its values in the
        // header. At the end of input, T_EOF. A lexical error (an unterminated
        // string) is T_ERR with the status latched.
        int end = emon.Port.CellsAt(ar, AEnd);
        int p = PlSkip(src, emon.Port.CellsAt(ar, APos), end);
        int c = 0;
        int q = 0;
        int t = 0;
        if (p >= end) {
            return PlTok(ar, 0, p, p, 0, 0, 0);
        }
        c = Pdfsrc.PsU8(src, p);
        if (c == 47) {
            return PlLexName(src, ar, p + 1, end);
        }
        if (c == 40) {
            return PlLexLit(src, ar, p + 1, end);
        }
        if (c == 91) {
            return PlTok(ar, 5, p, p + 1, 0, 0, 0);
        }
        if (c == 93) {
            return PlTok(ar, 6, p, p + 1, 0, 0, 0);
        }
        if (c == 123) {
            return PlTok(ar, 9, p, p + 1, 0, 0, 0);
        }
        if (c == 125) {
            return PlTok(ar, 10, p, p + 1, 0, 0, 0);
        }
        if (c == 60) {
            if (((p + 1) < end) && (Pdfsrc.PsU8(src, p + 1) == 60)) {
                return PlTok(ar, 7, p, p + 2, 0, 0, 0);
            }
            return PlLexHex(src, ar, p + 1, end);
        }
        if (c == 62) {
            if (((p + 1) < end) && (Pdfsrc.PsU8(src, p + 1) == 62)) {
                return PlTok(ar, 8, p, p + 2, 0, 0, 0);
            }
            return PlTokErr(ar, p, p + 1, 2);
        }
        if (c == 41) {
            return PlTokErr(ar, p, p + 1, 2);
        }
        if ((c == 43) || (c == 45) || (c == 46) || ((c >= 48) && (c <= 57))) {
            t = PlLexNumber(src, ar, p, end);
            if (t != 0) {
                return t;
            }
        }
        // A keyword: the run of regular characters.
        q = p;
        while ((q < end) && (PlRegular(Pdfsrc.PsU8(src, q)) == 1)) {
            q += 1;
        }
        return PlTok(ar, 11, p, q, p, q - p, PlKwIdOf(src, p, q - p));
    }
    public static int PlUnread(emon.Port.Cells ar) {
        // Put the last token back: the next `pl-lex` reads it again.
        emon.Port.CellsSet(ar, APos, emon.Port.CellsAt(ar, ATs));
        return 0;
    }
    internal static int PlEndsContainer(emon.Port.Cells ar, int tk) {
        // 1 when the token is one that closes a container the wrong way:
        // a dictionary's `>>` inside an array, or `endobj`, `endstream`,
        // `stream` or `obj`, which only ever occur outside one.
        if (tk == 8) {
            return 1;
        }
        if (tk == 11) {
            int id = emon.Port.CellsAt(ar, ATc);
            if ((id == 4) || (id == 5)) {
                return 1;
            }
            if ((id == 6) || (id == 7)) {
                return 1;
            }
        }
        return 0;
    }
    internal static int PlArrayStep(emon.Port.Src src, emon.Port.Cells ar, int arr) {
        // One element of an array: 0 carry on, 1 the array is complete, 2 failed.
        int tk = PlLex(src, ar);
        int v = 0;
        if (tk == 6) {
            return 1;
        }
        if (tk == 0) {
            PlFail(ar, 4);
            return 2;
        }
        if (tk == 12) {
            return 2;
        }
        if (PlEndsContainer(ar, tk) == 1) {
            PlUnread(ar);
            PlWarnSet(ar, 1);
            return 1;
        }
        v = PlValue(src, ar, tk);
        if (v == 0) {
            return 2;
        }
        PlAddChild(ar, arr, v);
        return 0;
    }
    internal static int PlArray(emon.Port.Src src, emon.Port.Cells ar) {
        // After `[`: the elements up to `]`. Answers the array, or 0.
        int arr = PlNew(ar, 6, 0, 0, 0);
        int st = 0;
        while (st == 0) {
            st = PlArrayStep(src, ar, arr);
        }
        if (st == 2) {
            return 0;
        }
        return arr;
    }
    internal static int PlDictStep(emon.Port.Src src, emon.Port.Cells ar, int d) {
        // One key/value pair of a dictionary: 0 carry on, 1 the dictionary is
        // complete, 2 failed. A key that is not a name is skipped (with its
        // value, if it starts one); a key with no value gets null.
        int tk = PlLex(src, ar);
        int tv = 0;
        int key = 0;
        int nv = 0;
        int v = 0;
        if (tk == 8) {
            return 1;
        }
        if (tk == 0) {
            PlFail(ar, 5);
            return 2;
        }
        if (tk == 12) {
            return 2;
        }
        if (PlEndsContainer(ar, tk) == 1) {
            PlUnread(ar);
            PlWarnSet(ar, 1);
            return 1;
        }
        if (tk != 3) {
            PlWarnSet(ar, 2);
            if ((tk != 6) && (tk != 10)) {
                v = PlValue(src, ar, tk);
                if (v == 0) {
                    return 2;
                }
            }
            return 0;
        }
        key = PlValue(src, ar, tk);
        tv = PlLex(src, ar);
        if (tv == 8) {
            nv = PlNew(ar, 0, 0, 0, 0);
            PlAddChild(ar, d, key);
            PlAddChild(ar, d, nv);
            return 1;
        }
        if (tv == 0) {
            PlFail(ar, 5);
            return 2;
        }
        if (tv == 12) {
            return 2;
        }
        if (PlEndsContainer(ar, tv) == 1) {
            PlUnread(ar);
            PlWarnSet(ar, 1);
            nv = PlNew(ar, 0, 0, 0, 0);
            PlAddChild(ar, d, key);
            PlAddChild(ar, d, nv);
            return 1;
        }
        v = PlValue(src, ar, tv);
        if (v == 0) {
            return 2;
        }
        PlAddChild(ar, d, key);
        PlAddChild(ar, d, v);
        return 0;
    }
    internal static int PlDict(emon.Port.Src src, emon.Port.Cells ar) {
        // After `<<`: the pairs up to `>>`. Answers the dictionary, or 0.
        int d = PlNew(ar, 7, 0, 0, 0);
        int st = 0;
        while (st == 0) {
            st = PlDictStep(src, ar, d);
        }
        if (st == 2) {
            return 0;
        }
        return d;
    }
    internal static int PlRefOrInt(emon.Port.Src src, emon.Port.Cells ar, int num, int wrapped) {
        // An integer has just been read. `num 0 R` is a reference: look
        // ahead two tokens, and only if a digit follows, so a string or a
        // dictionary is never lexed twice.
        int end = emon.Port.CellsAt(ar, AEnd);
        int after = emon.Port.CellsAt(ar, APos);
        int p = PlSkip(src, after, end);
        int t2 = 0;
        int t3 = 0;
        int gen = 0;
        if (num < 0) {
            return PlNew(ar, 2, num, 0, wrapped);
        }
        if (p >= end) {
            return PlNew(ar, 2, num, 0, wrapped);
        }
        if ((Pdfsrc.PsU8(src, p) < 48) || (Pdfsrc.PsU8(src, p) > 57)) {
            return PlNew(ar, 2, num, 0, wrapped);
        }
        t2 = PlLex(src, ar);
        if (t2 == 1) {
            gen = emon.Port.CellsAt(ar, ATa);
            if (gen >= 0) {
                t3 = PlLex(src, ar);
                if ((t3 == 11) && (emon.Port.CellsAt(ar, ATc) == 8)) {
                    return PlNew(ar, 9, num, gen, 0);
                }
            }
        }
        emon.Port.CellsSet(ar, APos, after);
        return PlNew(ar, 2, num, 0, wrapped);
    }
    internal static int PlValue(emon.Port.Src src, emon.Port.Cells ar, int tk) {
        // The object whose first token `tk` has just been lexed, or 0.
        int ta = emon.Port.CellsAt(ar, ATa);
        int tb = emon.Port.CellsAt(ar, ATb);
        int tc = emon.Port.CellsAt(ar, ATc);
        int v = 0;
        int k = 0;
        int at = 0;
        if (tk == 0) {
            return PlFail(ar, 1);
        }
        if (tk == 12) {
            return 0;
        }
        if (tk == 1) {
            return PlRefOrInt(src, ar, ta, tc);
        }
        if (tk == 2) {
            return PlNew(ar, 3, ta, tb, 0);
        }
        if (tk == 3) {
            return PlNew(ar, 4, ta, tb, 0);
        }
        if (tk == 4) {
            return PlNew(ar, 5, ta, tb, tc);
        }
        if ((tk == 5) || (tk == 7)) {
            if (emon.Port.CellsAt(ar, ADepth) >= MaxNest) {
                return PlFail(ar, 6);
            }
            emon.Port.CellsSet(ar, ADepth, emon.Port.CellsAt(ar, ADepth) + 1);
            if (tk == 5) {
                v = PlArray(src, ar);
            } else {
                v = PlDict(src, ar);
            }
            emon.Port.CellsSet(ar, ADepth, emon.Port.CellsAt(ar, ADepth) - 1);
            return v;
        }
        if (tk == 11) {
            if (tc == KTrue) {
                return PlNew(ar, 1, 1, 0, 0);
            }
            if (tc == KFalse) {
                return PlNew(ar, 1, 0, 0, 0);
            }
            if (tc == KNull) {
                return PlNew(ar, 0, 0, 0, 0);
            }
            // Any other keyword is an object of its own (a content-stream
            // operator); its bytes are copied into the arena.
            at = emon.Port.CellsLen(ar);
            k = 0;
            while (k < tb) {
                emon.Port.CellsPush(ar, Pdfsrc.PsU8(src, ta + k));
                k += 1;
            }
            return PlNew(ar, 10, at, tb, tc);
        }
        return PlFail(ar, 2);
    }
    public static int PlParse(emon.Port.Src src, emon.Port.Cells ar) {
        // Parse one object at the current position. Answers its handle, or 0
        // with `(pl-err ar)` set. A keyword that is not true, false or null
        // (an operator, or `endobj`) answers a keyword object, so a content
        // stream can be read as operands followed by one.
        emon.Port.CellsSet(ar, ADepth, 0);
        int tk = PlLex(src, ar);
        int v = PlValue(src, ar, tk);
        if (Pdfsrc.PsMissed(src)) {
            return PlMiss(ar);
        }
        return v;
    }
    internal static int PlFindEndstream(emon.Port.Src src, int from, int end) {
        // The index of the first `endstream` at or after from, or -1.
        int i = from;
        while (i < end) {
            if (Pdfsrc.PsU8(src, i) == 101) {
                if (PlKwAt(src, i, end, KEndstream) == 1) {
                    return i;
                }
            }
            if (PlStalled(src, i) == 1) {
                return -1;
            }
            i += 1;
        }
        return -1;
    }
    internal static int PlFindEndobj(emon.Port.Src src, int from, int end) {
        int i = from;
        while (i < end) {
            if (Pdfsrc.PsU8(src, i) == 101) {
                if (PlKwAt(src, i, end, KEndobj) == 1) {
                    return i;
                }
            }
            if (PlStalled(src, i) == 1) {
                return -1;
            }
            i += 1;
        }
        return -1;
    }
    internal static int PlScan(emon.Port.Src src, emon.Port.Cells ar, int start, int end) {
        // The data length of a stream starting at `start`, found by scanning for
        // `endstream` (none: `endobj`, none: the end), with one end of line
        // before it dropped. The index after what the scan found is left in the
        // header's token slot B for the caller. THE ONE WHOLE-STREAM SCAN: it
        // runs only when /Length is wrong or missing, never for a good one.
        int e = PlFindEndstream(src, start, end);
        int z = 0;
        int after = 0;
        if (e < 0) {
            PlWarnSet(ar, 8);
            e = PlFindEndobj(src, start, end);
            if (e < 0) {
                e = end;
            }
            after = e;
        } else {
            after = e + 9;
        }
        z = e;
        if ((z > start) && (Pdfsrc.PsU8(src, z - 1) == 10)) {
            z -= 1;
        }
        if ((z > start) && (Pdfsrc.PsU8(src, z - 1) == 13)) {
            z -= 1;
        }
        emon.Port.CellsSet(ar, ATb, after);
        return z - start;
    }
    public static int PlStreamRescan(emon.Port.Src src, emon.Port.Cells ar, int sh) {
        // Find a stream's length by scanning, for the caller that could not use
        // an indirect /Length: sets the length and marks it scanned (flags 1).
        int start = emon.Port.CellsAt(ar, sh + RB);
        int dlen = PlScan(src, ar, start, Pdfsrc.PsLen(src));
        emon.Port.CellsSet(ar, sh + RC, dlen);
        emon.Port.CellsSet(ar, sh + RD, 1);
        PlWarnSet(ar, 4);
        return dlen;
    }
    internal static int PlStream(emon.Port.Src src, emon.Port.Cells ar, int dict) {
        // After the `stream` keyword: the data span. The keyword is followed
        // by CRLF or LF (a lone CR, and spaces before the end of line, are
        // tolerated and noted). A direct /Length is trusted only when
        // `endstream` follows the data it names; a wrong or missing one is
        // replaced by a scan for `endstream`. An INDIRECT /Length cannot be
        // resolved here and is NOT scanned for: the stream is marked (flags 2)
        // with length 0 and the document layer resolves the reference, or calls
        // `pl-stream-rescan` when that fails. Reading a file does not read
        // through every stream.
        int end = emon.Port.CellsAt(ar, AEnd);
        int kwEnd = emon.Port.CellsAt(ar, APos);
        int p = kwEnd;
        int start = 0;
        int flags = 0;
        int dlen = -1;
        int lh = 0;
        int lk = 0;
        int n = 0;
        int z = 0;
        int sh = 0;
        int after = 0;
        while ((p < end) && ((Pdfsrc.PsU8(src, p) == 32) || (Pdfsrc.PsU8(src, p) == 9))) {
            p += 1;
        }
        if ((p < end) && (Pdfsrc.PsU8(src, p) == 13)) {
            p += 1;
            if ((p < end) && (Pdfsrc.PsU8(src, p) == 10)) {
                p += 1;
            } else {
                PlWarnSet(ar, 32);
            }
        } else if ((p < end) && (Pdfsrc.PsU8(src, p) == 10)) {
            p += 1;
        } else {
            p = kwEnd;
            PlWarnSet(ar, 32);
        }
        start = p;
        lh = PlDictGet(ar, dict, Pdfnames.PnLength());
        if (lh != 0) {
            lk = emon.Port.CellsAt(ar, lh + RKind);
            if (lk == 2) {
                n = emon.Port.CellsAt(ar, lh + RA);
                if ((n >= 0) && (n <= (end - start))) {
                    z = PlSkip(src, start + n, end);
                    if (PlKwAt(src, z, end, KEndstream) == 1) {
                        dlen = n;
                        after = z + 9;
                    }
                }
            }
            if (lk == 9) {
                flags = 2;
                dlen = 0;
                after = start;
            }
        }
        if (dlen < 0) {
            flags = 1;
            PlWarnSet(ar, 4);
            dlen = PlScan(src, ar, start, end);
            after = emon.Port.CellsAt(ar, ATb);
        }
        emon.Port.CellsSet(ar, APos, after);
        sh = PlNew(ar, 8, dict, start, dlen);
        emon.Port.CellsSet(ar, sh + RD, flags);
        return sh;
    }
    internal static int PlParseIndirectRun(emon.Port.Src src, emon.Port.Cells ar, int pos) {
        // `pl-parse-indirect` without its checkpoint.
        emon.Port.CellsSet(ar, APos, PlClamp(pos, emon.Port.CellsAt(ar, AEnd)));
        emon.Port.CellsSet(ar, AErr, 0);
        emon.Port.CellsSet(ar, ADepth, 0);
        int tk = PlLex(src, ar);
        int num = 0;
        int gen = 0;
        int v = 0;
        if (tk != 1) {
            return PlFail(ar, 7);
        }
        num = emon.Port.CellsAt(ar, ATa);
        tk = PlLex(src, ar);
        if (tk != 1) {
            return PlFail(ar, 7);
        }
        gen = emon.Port.CellsAt(ar, ATa);
        tk = PlLex(src, ar);
        if ((tk != 11) || (emon.Port.CellsAt(ar, ATc) != KObj)) {
            return PlFail(ar, 7);
        }
        if ((num < 0) || (gen < 0)) {
            return PlFail(ar, 7);
        }
        emon.Port.CellsSet(ar, AObjnum, num);
        emon.Port.CellsSet(ar, AObjgen, gen);
        tk = PlLex(src, ar);
        v = PlValue(src, ar, tk);
        if (v == 0) {
            return 0;
        }
        if (emon.Port.CellsAt(ar, v + RKind) == 7) {
            tk = PlLex(src, ar);
            if ((tk == 11) && (emon.Port.CellsAt(ar, ATc) == KStream)) {
                v = PlStream(src, ar, v);
            } else {
                PlUnread(ar);
            }
        }
        // An indirect-length stream's end is not known yet: the next bytes are
        // its data, not an `endobj`.
        if ((emon.Port.CellsAt(ar, v + RKind) == 8) && (emon.Port.CellsAt(ar, v + RD) == 2)) {
            return v;
        }
        tk = PlLex(src, ar);
        if ((tk != 11) || (emon.Port.CellsAt(ar, ATc) != KEndobj)) {
            PlWarnSet(ar, 16);
            PlUnread(ar);
        }
        return v;
    }
    public static int PlParseIndirect(emon.Port.Src src, emon.Port.Cells ar, int pos) {
        // Parse `N G obj <object> [stream ... endstream] endobj` at pos.
        // Answers the object (a stream object when there is a stream) and
        // leaves N, G in `pl-objnum`/`pl-objgen`; 0 with the error latched
        // otherwise. The position after it is `pl-pos`. A CHECKPOINT (D058):
        // when a read of `src` missed, the answer is 0 and the error
        // `need-bytes`, whatever the zeros looked like.
        int v = PlParseIndirectRun(src, ar, pos);
        if (Pdfsrc.PsMissed(src)) {
            return PlMiss(ar);
        }
        return v;
    }
    internal static int PlHexDigit(System.Text.StringBuilder t, int v) {
        if (v < 10) {
            emon.Port.TextCp(t, 48 + v);
        } else {
            emon.Port.TextCp(t, 87 + v);
        }
        return 0;
    }
    internal static int PlDigitAt(int m, int i) {
        // The decimal digit of m at position i from the right (0 is the units).
        int x = m;
        int k = 0;
        while (k < i) {
            x = x / 10;
            k += 1;
        }
        return x % 10;
    }
    internal static int PlDumpReal(System.Text.StringBuilder t, int a, int scale) {
        // mantissa a over 10^scale, as the digits it was written with.
        int m = a;
        int nd = 1;
        int x = 0;
        int total = 0;
        int i = 0;
        if (m < 0) {
            emon.Port.TextAscii(t, "-");
            m = 0 - m;
        }
        x = m / 10;
        while (x > 0) {
            nd += 1;
            x = x / 10;
        }
        total = nd;
        if (total < (scale + 1)) {
            total = scale + 1;
        }
        i = total - 1;
        while (i >= 0) {
            emon.Port.TextCp(t, 48 + PlDigitAt(m, i));
            if ((i == scale) && (scale >= 0)) {
                emon.Port.TextAscii(t, ".");
            }
            i -= 1;
        }
        return 0;
    }
    internal static int PlDumpName(System.Text.StringBuilder t, emon.Port.Cells ar, int h) {
        int n = emon.Port.CellsAt(ar, h + RB);
        int e = emon.Port.CellsAt(ar, h + RA);
        int i = 0;
        int c = 0;
        emon.Port.TextAscii(t, "/");
        while (i < n) {
            c = emon.Port.CellsAt(ar, e + (2 + i));
            if ((c <= 32) || (c >= 127) || (PlIsDelim(c) == 1) || (c == 35)) {
                emon.Port.TextAscii(t, "#");
                PlHexDigit(t, c / 16);
                PlHexDigit(t, c % 16);
            } else {
                emon.Port.TextCp(t, c);
            }
            i += 1;
        }
        return 0;
    }
    public static int PlDump(System.Text.StringBuilder t, emon.Port.Cells ar, int h) {
        // An object as canonical text: `null`, `true`, `-12`, `3.50`,
        // `/Na#20me`, `<48656c>` (every string in hex), `[1 2]`, `<< /A 1 >>`,
        // `3 0 R`, `stream@start+length` after the dictionary (`~scan` or
        // `~ref` when the length was not trusted), and `kw:name` for a
        // keyword. Answers 0.
        int kind = emon.Port.CellsAt(ar, h + RKind);
        int a = emon.Port.CellsAt(ar, h + RA);
        int b = emon.Port.CellsAt(ar, h + RB);
        int c = emon.Port.CellsAt(ar, h + RC);
        int k = 0;
        int x = 0;
        int first = 1;
        if (kind == 0) {
            emon.Port.TextAscii(t, "null");
        }
        if (kind == 1) {
            if (a == 1) {
                emon.Port.TextAscii(t, "true");
            } else {
                emon.Port.TextAscii(t, "false");
            }
        }
        if (kind == 2) {
            emon.Port.TextI32(t, a);
        }
        if (kind == 3) {
            PlDumpReal(t, a, b);
        }
        if (kind == 4) {
            PlDumpName(t, ar, h);
        }
        if (kind == 5) {
            emon.Port.TextAscii(t, "<");
            k = 0;
            while (k < b) {
                x = emon.Port.CellsAt(ar, a + k);
                PlHexDigit(t, x / 16);
                PlHexDigit(t, x % 16);
                k += 1;
            }
            emon.Port.TextAscii(t, ">");
        }
        if (kind == 6) {
            emon.Port.TextAscii(t, "[");
            k = a;
            while (k != 0) {
                if (first == 0) {
                    emon.Port.TextAscii(t, " ");
                }
                first = 0;
                PlDump(t, ar, k);
                k = emon.Port.CellsAt(ar, k + RNext);
            }
            emon.Port.TextAscii(t, "]");
        }
        if (kind == 7) {
            emon.Port.TextAscii(t, "<<");
            k = a;
            while (k != 0) {
                emon.Port.TextAscii(t, " ");
                PlDump(t, ar, k);
                k = emon.Port.CellsAt(ar, k + RNext);
            }
            emon.Port.TextAscii(t, " >>");
        }
        if (kind == 8) {
            PlDump(t, ar, a);
            emon.Port.TextAscii(t, " stream@");
            emon.Port.TextI32(t, b);
            emon.Port.TextAscii(t, "+");
            emon.Port.TextI32(t, c);
            x = emon.Port.CellsAt(ar, h + RD);
            if (x == 1) {
                emon.Port.TextAscii(t, "~scan");
            }
            if (x == 2) {
                emon.Port.TextAscii(t, "~ref");
            }
        }
        if (kind == 9) {
            emon.Port.TextI32(t, a);
            emon.Port.TextAscii(t, " ");
            emon.Port.TextI32(t, b);
            emon.Port.TextAscii(t, " R");
        }
        if (kind == 10) {
            emon.Port.TextAscii(t, "kw:");
            k = 0;
            while (k < b) {
                emon.Port.TextCp(t, emon.Port.CellsAt(ar, a + k));
                k += 1;
            }
        }
        return 0;
    }
}
